  }
  if (aStatusCode == Cr.NS_OK) {
    this._resolve(this._resolveValue);
  } else {
    this._reject(new Error(aStatusCode));
  }
}

    if (this._readBytes) {
      this._resolveValue += this._stream.readBytes(aCount);
    } else {
      this._resolveValue += this._stream.read(aCount);
    }
  }
};
